<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class SupportMessage extends Model{protected $fillable=['conversation_id','sender_id','body','type','attachment_path','read_at'];protected $casts=['read_at'=>'datetime'];protected $appends=['attachment_url'];public function conversation(){return $this->belongsTo(SupportConversation::class);}public function sender(){return $this->belongsTo(User::class,'sender_id');}public function getAttachmentUrlAttribute(){return $this->attachment_path?\Storage::url($this->attachment_path):null;}}